import sys

def main():
    data = sys.stdin.read().split()
    s, t = data[0], data[1]
    MOD = 10**9 + 7
    n, m = len(s), len(t)
    pw = [1] * (n + 1)
    for i in range(1, n + 1):
        pw[i] = pw[i - 1] * 2 % MOD
    pos = {}
    for j, ch in enumerate(t):
        pos.setdefault(ch, []).append(j)
    for ch in pos:
        pos[ch].reverse()
    cnt = [0] * (m + 1)
    cnt[0] = 1
    ans = 0
    for p in range(n):
        c = s[p]
        tot = cnt[m]
        for j in range(m):
            if t[j] < c:
                tot += cnt[j]
        ans = (ans + tot % MOD * pw[n - p - 1]) % MOD
        for j in pos.get(c, ()):
            cnt[j + 1] = (cnt[j + 1] + cnt[j]) % MOD
    print(ans)

main()

